import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import EditVist from "@/components/PresenceApp/PopUps/EditVist.vue";
import { formatedatetime } from "@/JsonFiles/DateFormate.js";
import { list_presence_visitors } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar,
    EditVist
  },
  data() {
    return {
      search: "",
      tableLoading: false,
      visitorEdition: false,
      tableData: [],
      SnackBarComponent: {},
      rowInfo: {},
      componentCheck: 0,
      fixed: true,
      pagination: {
        itemsPerPage: 20,
        page: 1
      },
      itemsPerPage: 10,
      currentPage: 1,
      totalCount: 0,
      sortedAndPaginatedItems: [],
      headers: [{
        title: "RFID",
        value: "rfid",
        sortable: false
      }, {
        title: "Visitor",
        value: "visitor_name",
        sortable: false
      }, {
        title: "Last Visited On",
        value: "last_swiped_on",
        sortable: false
      }, {
        title: "Action",
        value: "actions",
        sortable: false
      }],
      windowHeight: 0
    };
  },
  created() {
    this.windowHeight = window.innerHeight - 280;
    this.get_vistor_list();
  },
  computed: {
    pageCount() {
      return Math.ceil(this.totalCount / this.itemsPerPage);
    },
    paginatedItems() {
      if (!this.tableData || this.tableData.length === 0) {
        return [];
      }
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.tableData.slice(start, end);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  methods: {
    get_date(val) {
      return formatedatetime(val / 1000);
    },
    edit_vist(item) {
      this.componentCheck = 1;
      this.rowInfo = item;
      this.visitorEdition = true;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.visitorEdition = false;
      this.tableData = [];
      this.get_vistor_list();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async get_vistor_list() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(list_presence_visitors, {}));
        this.tableLoading = false;
        var response = JSON.parse(result.data.list_presence_visitors);
        if (response.Status == "SUCCESS") {
          let array = this.tableData.concat(response.data || []);
          this.tableData = array;
          const uniqueArrayOfObjects = this.tableData.filter((obj, index, self) => index === self.findIndex(o => o.visitor_id === obj.visitor_id));
          this.tableData = uniqueArrayOfObjects;
          this.totalCount = this.tableData.length;
          this.sortedAndPaginatedItems = this.tableData;

          // Ensure currentPage doesn't exceed available pages
          const maxPage = Math.ceil(this.totalCount / this.itemsPerPage);
          if (this.currentPage > maxPage && maxPage > 0) {
            this.currentPage = maxPage;
          }
        } else {
          this.tableLoading = false;
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    handleSortChange(_newSortBy) {
      // Implement the logic to handle sort change
    }
  }
};
